}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "append">append</param>
public void create(boolean append)
{
    next create();
    ProdParmRelease     prodParmRelease = this.cursor();
    FormRun             formRun = this.formRun();
    FormControl         setupPrintProdProdOrderCtr = formRun.design().controlName(formControlStr(ProdParmRelease,AVASetupButtonProdProdOrder));
    FormControl         setupPrintProdRunMapCtr    = formRun.design().controlName(formControlStr(ProdParmRelease,AVASetupButtonProdRunMap));

    if (setupPrintProdProdOrderCtr)
    {
        setupPrintProdProdOrderCtr.enabled(prodParmRelease.AVAPrintProdProdOrder);
    }

    if (setupPrintProdRunMapCtr)
    {
        setupPrintProdRunMapCtr.enabled(prodParmRelease.AVAPrintProdRunMap);
    }
}

int active()
{
    int  ret = next active();
    ProdParmRelease     prodParmRelease = this.cursor();
    FormRun             formRun = this.formRun();
    FormControl         setupPrintProdProdOrderCtr = formRun.design().controlName(formControlStr(ProdParmRelease,AVASetupButtonProdProdOrder));
    FormControl         setupPrintProdRunMapCtr    = formRun.design().controlName(formControlStr(ProdParmRelease,AVASetupButtonProdRunMap));

    FormControl         prodOrderPrintReferenceCtr = formRun.design().controlName(formControlStr(ProdParmRelease,ProdParmRelease_AVAPrintReference));
    FormControl         prodOrderPrintReferenceRunMapCtr = formRun.design().controlName(formControlStr(ProdParmRelease,ProdParmRelease_AVAPrintReferenceRunMap));

    if (setupPrintProdProdOrderCtr)
    {
        setupPrintProdProdOrderCtr.enabled(prodParmRelease.AVAPrintProdProdOrder);
    }

    if (prodOrderPrintReferenceCtr)
    {
        prodOrderPrintReferenceCtr.enabled(prodParmRelease.AVAPrintProdProdOrder);
    }

    if (setupPrintProdRunMapCtr)
    {
        setupPrintProdRunMapCtr.enabled(prodParmRelease.AVAPrintProdRunMap);

    }
    if (prodOrderPrintReferenceRunMapCtr)
    {
        prodOrderPrintReferenceRunMapCtr.enabled(prodParmRelease.AVAPrintProdRunMap);

    }

    return ret;
}
